usage.code:
import { BounceCards } from "solen-design/react";

const images = [
  "/photos/one.jpg",
  "/photos/two.jpg",
  { src: "/photos/three.jpg", alt: "Third card" },
  "/photos/four.jpg",
  "/photos/five.jpg"
];

<BounceCards
  images={images}
  containerWidth={400}
  containerHeight={400}
  cardSize={200}
  spread={85}
  rotation={10}
  arc={0}
  animationDelay={0.5}
  animationStagger={0.06}
  bounciness={0.6}
  enableHover={true}
  pushDistance={160}
  hoverScale={1.06}
  borderWidth={5}
  borderColor="#ffffff"
  radius={25}
  shadow={true}
  onCardClick={(index) => console.log(index)}
/>
